//! Golden-fixture, causality, determinism, and edge-case tests for the
//! axis-agreement strategy.
//!
//! The fixture is a checked-in CSV of synthetic readings and the decision each
//! bar must produce. Its expected values are hand-derived from the rule in the
//! program plan: a strict threshold comparison, equality neutral, a missing
//! reading unavailable, and no reversal on the exit bar. The fixture is not
//! generated by the code under test.
//!
//! An empty reading cell is an unavailable measurement; a numeric cell is a
//! measured value, and a measured zero is written as `0.0`.

use quantrule_backtest::strategy::{
    AxisAgreementStrategy, Decision, Side, Strategy, StrategyConfig, StrategyInput,
};

const FIXTURE: &str = include_str!("fixtures/agreement_strategy_golden.csv");
const HEADER: &str = "bar,timestamp,timeframe_secs,direction,momentum_force,structure_score,expected_decision,expected_side,expected_reason,expected_position";

#[derive(Debug, Clone)]
struct GoldenRow {
    input: StrategyInput,
    decision: String,
    side: String,
    reason: String,
    position: String,
}

fn number(field: &str) -> Option<f64> {
    if field.is_empty() {
        None
    } else {
        Some(
            field
                .parse::<f64>()
                .unwrap_or_else(|error| panic!("invalid number {field:?}: {error}")),
        )
    }
}

fn integer<T>(field: &str) -> T
where
    T: std::str::FromStr,
    T::Err: std::fmt::Display,
{
    field
        .parse::<T>()
        .unwrap_or_else(|error| panic!("invalid integer {field:?}: {error}"))
}

fn load() -> Vec<GoldenRow> {
    let mut lines = FIXTURE.lines();
    assert_eq!(lines.next(), Some(HEADER), "fixture header changed");

    let mut rows = Vec::new();
    for line in lines {
        let fields: Vec<&str> = line.split(',').collect();
        assert_eq!(fields.len(), 10, "wrong column count in {line:?}");

        let bar = integer::<usize>(fields[0]);
        assert_eq!(bar, rows.len(), "fixture bars must be contiguous");

        let input = StrategyInput::new(
            integer::<u64>(fields[2]),
            bar,
            integer::<i64>(fields[1]),
            number(fields[3]),
            number(fields[4]),
            number(fields[5]),
        );

        rows.push(GoldenRow {
            input,
            decision: fields[6].to_owned(),
            side: fields[7].to_owned(),
            reason: fields[8].to_owned(),
            position: fields[9].to_owned(),
        });
    }
    rows
}

fn side_label(side: Side) -> &'static str {
    match side {
        Side::Long => "long",
        Side::Short => "short",
    }
}

fn position_label(position: Option<Side>) -> &'static str {
    match position {
        Some(side) => side_label(side),
        None => "",
    }
}

fn parts(decision: Decision) -> (&'static str, &'static str, &'static str) {
    match decision {
        Decision::Hold => ("hold", "", ""),
        Decision::Enter(entry) => ("enter", side_label(entry.side), ""),
        Decision::Exit(exit) => ("exit", side_label(exit.side), "agreement_lost"),
    }
}

fn run(strategy: &mut AxisAgreementStrategy, inputs: &[StrategyInput]) -> Vec<Decision> {
    inputs.iter().map(|input| strategy.on_bar(input)).collect()
}

#[test]
fn the_strategy_matches_the_golden_fixture() {
    let rows = load();
    assert_eq!(rows.len(), 26, "fixture row count changed");
    let mut strategy = AxisAgreementStrategy::new(StrategyConfig::default());

    for row in &rows {
        let decision = strategy.on_bar(&row.input);
        let (kind, side, reason) = parts(decision);

        assert_eq!(kind, row.decision, "bar {} decision", row.input.bar_index);
        assert_eq!(side, row.side, "bar {} side", row.input.bar_index);
        assert_eq!(reason, row.reason, "bar {} reason", row.input.bar_index);
        assert_eq!(
            position_label(strategy.position()),
            row.position,
            "bar {} position",
            row.input.bar_index
        );

        match decision {
            Decision::Enter(entry) => assert_eq!(entry.bar, row.input),
            Decision::Exit(exit) => assert_eq!(exit.bar, row.input),
            Decision::Hold => {}
        }
    }
}

#[test]
fn later_bars_do_not_change_earlier_decisions() {
    let rows = load();
    let inputs: Vec<StrategyInput> = rows.iter().map(|row| row.input).collect();
    let prefix = 13;

    let mut prefix_strategy = AxisAgreementStrategy::default();
    let prefix_decisions = run(&mut prefix_strategy, &inputs[..prefix]);

    let mut full_strategy = AxisAgreementStrategy::default();
    let full_decisions = run(&mut full_strategy, &inputs);
    assert_eq!(full_decisions[..prefix], prefix_decisions);

    let mut changed = inputs.clone();
    changed[prefix] = StrategyInput::new(
        900,
        prefix,
        changed[prefix].open_time,
        Some(0.9),
        Some(0.9),
        Some(0.9),
    );
    let mut changed_strategy = AxisAgreementStrategy::default();
    let changed_decisions = run(&mut changed_strategy, &changed);
    assert_eq!(changed_decisions[..prefix], prefix_decisions);
}

#[test]
fn repeated_runs_are_identical() {
    let inputs: Vec<StrategyInput> = load().iter().map(|row| row.input).collect();

    let mut first = AxisAgreementStrategy::default();
    let expected = run(&mut first, &inputs);

    for _ in 0..10 {
        let mut again = AxisAgreementStrategy::default();
        assert_eq!(run(&mut again, &inputs), expected);
    }
}

#[test]
fn an_empty_series_produces_no_decisions() {
    let mut strategy = AxisAgreementStrategy::default();

    assert!(run(&mut strategy, &[]).is_empty());
    assert_eq!(strategy.position(), None);
}

#[test]
fn a_single_bar_can_open_a_position() {
    let input = StrategyInput::new(900, 0, 0, Some(0.2), Some(0.5), Some(1.0));
    let mut strategy = AxisAgreementStrategy::default();

    assert_eq!(
        strategy.on_bar(&input),
        Decision::Enter(quantrule_backtest::strategy::Entry {
            side: Side::Long,
            bar: input,
        })
    );
    assert_eq!(strategy.position(), Some(Side::Long));
}

#[test]
fn a_short_history_with_missing_readings_stays_flat() {
    let inputs = [
        StrategyInput::new(900, 0, 0, None, None, None),
        StrategyInput::new(900, 1, 900, Some(0.2), None, Some(1.0)),
        StrategyInput::new(900, 2, 1_800, Some(0.2), Some(0.5), None),
    ];
    let mut strategy = AxisAgreementStrategy::default();

    assert_eq!(run(&mut strategy, &inputs), vec![Decision::Hold; 3]);
    assert_eq!(strategy.position(), None);
}
